{"kind":"patch","files":{"evals/ooo-execution/fixtures/pipeline/frozen.ts":"/**
 * The frozen interface of the pipeline report this task family builds.
 *
 * Nothing here is anyone's unit: it is the contract the builders are written to, and the only
 * renderer. A finer plan is the same work precisely because this file stays as it is.
 */
export interface Step {
  readonly name: string;
  readonly ms: number;
}

/** The one renderer: a step is its name and its duration. */
export function renderStep(step: Step): string {
  return `${step.name}: ${step.ms}ms`;
}
","evals/ooo-execution/fixtures/pipeline/normalize.test.ts":"import assert from "node:assert/strict";
import test from "node:test";

import { normalize } from "./normalize.ts";

test("normalize keeps the steps that took time, in name order", () => {
  assert.deepEqual(
    normalize([
      { name: "b", ms: 2 },
      { name: "x", ms: 0 },
      { name: "a", ms: 1 },
    ]),
    [
      { name: "a", ms: 1 },
      { name: "b", ms: 2 },
    ],
  );
  assert.deepEqual(normalize([]), []);
});
","evals/ooo-execution/fixtures/pipeline/normalize.ts":"import type { Step } from "./frozen.ts";

/** The steps the report is built from: only the ones that took time, in name order. */
export function normalize(steps: readonly Step[]): Step[] {
  return steps
    .filter((step) => step.ms > 0)
    .sort((left, right) => (left.name < right.name ? -1 : left.name > right.name ? 1 : 0))
    .map((step) => ({ name: step.name, ms: step.ms }));
}
","evals/ooo-execution/fixtures/pipeline/pipeline.test.ts":"import assert from "node:assert/strict";
import test from "node:test";

import { normalize } from "./normalize.ts";
import { scale } from "./scale.ts";
import { summarize } from "./summarize.ts";
import { total } from "./total.ts";

/** The composition's own acceptance: the four builders over one input, rendered. */
test("the composed report is the four builders over one input", () => {
  const raw = [
    { name: "b", ms: 4 },
    { name: "x", ms: 0 },
    { name: "a", ms: 3 },
  ];
  const scaled = scale(normalize(raw), 2);
  assert.equal(summarize(scaled, total(scaled)), "a: 6ms\nb: 8ms\ntotal: 14ms");
});
","evals/ooo-execution/fixtures/pipeline/scale.test.ts":"import assert from "node:assert/strict";
import test from "node:test";

import { scale } from "./scale.ts";

test("scale multiplies every step and rounds down to whole milliseconds", () => {
  assert.deepEqual(scale([{ name: "a", ms: 3 }], 1.5), [{ name: "a", ms: 4 }]);
  assert.deepEqual(
    scale(
      [
        { name: "a", ms: 2 },
        { name: "b", ms: 1 },
      ],
      2,
    ),
    [
      { name: "a", ms: 4 },
      { name: "b", ms: 2 },
    ],
  );
  assert.deepEqual(scale([], 3), []);
});
","evals/ooo-execution/fixtures/pipeline/scale.ts":"import type { Step } from "./frozen.ts";

/** The same steps at another size: whole milliseconds, rounded down. */
export function scale(steps: readonly Step[], factor: number): Step[] {
  return steps.map((step) => ({ name: step.name, ms: Math.floor(step.ms * factor) }));
}
","evals/ooo-execution/fixtures/pipeline/summarize.test.ts":"import assert from "node:assert/strict";
import test from "node:test";

import type { Step } from "./frozen.ts";
import { summarize } from "./summarize.ts";

/** The summary's own acceptance needs the frozen interface and nothing else: which steps and which
 *  total it is handed is the composition's business, and the composed check is where the real
 *  builders meet. */
const steps: Step[] = [
  { name: "a", ms: 1 },
  { name: "b", ms: 2 },
];

test("the report lists the steps it was given, then the total it was given", () => {
  assert.equal(summarize(steps, 3), "a: 1ms\nb: 2ms\ntotal: 3ms");
  assert.equal(summarize([], 0), "total: 0ms");
});
","evals/ooo-execution/fixtures/pipeline/summarize.ts":"import type { Step } from "./frozen.ts";
import { renderStep } from "./frozen.ts";

/** The report: every step it was given, and the total it was given, rendered. Its input is the other
 *  three builders' results, which is why it can only be built once they exist. */
export function summarize(normalized: readonly Step[], totalMs: number): string {
  const lines = normalized.map((step) => renderStep(step));
  lines.push(renderStep({ name: "total", ms: totalMs }));
  return lines.join("\n");
}
","evals/ooo-execution/fixtures/pipeline/total.test.ts":"import assert from "node:assert/strict";
import test from "node:test";

import { total } from "./total.ts";

test("total adds the steps it was given, and an empty pipeline is zero", () => {
  assert.equal(
    total([
      { name: "a", ms: 1 },
      { name: "b", ms: 2 },
    ]),
    3,
  );
  assert.equal(total([]), 0);
});
","evals/ooo-execution/fixtures/pipeline/total.ts":"import type { Step } from "./frozen.ts";

/** The whole pipeline in one number: the sum of the steps it was given. */
export function total(steps: readonly Step[]): number {
  return steps.reduce((sum, step) => sum + step.ms, 0);
}
